const jobs = new Map(); // job_id -> status ('running' | 'cancelled')

export async function listTools() {
  return [
    {
      name: 'start_job',
      description: 'Start a job. Requires a job_id and returns running status. Rejects duplicate active jobs.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'The unique identifier for the job.' }
        },
        required: ['job_id'],
        additionalProperties: false
      }
    },
    {
      name: 'cancel_job',
      description: 'Cancel an active job. Requires a job_id, changes an active job to cancelled, and rejects missing jobs or repeated cancellation.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'The unique identifier for the job to cancel.' }
        },
        required: ['job_id'],
        additionalProperties: false
      }
    }
  ];
}

function textResult(text) {
  return { content: [{ type: 'text', text }] };
}

function invalidParams(message) {
  const err = new Error(message);
  err.code = -32602;
  return err;
}

export async function callTool(name, args = {}) {
  if (name === 'start_job') {
    if (typeof args.job_id !== 'string' || args.job_id.length === 0) {
      throw invalidParams('job_id is required');
    }
    const status = jobs.get(args.job_id);
    if (status === 'running') {
      throw invalidParams(`job ${args.job_id} is already running`);
    }
    jobs.set(args.job_id, 'running');
    return textResult(`job ${args.job_id} is running`);
  }

  if (name === 'cancel_job') {
    if (typeof args.job_id !== 'string' || args.job_id.length === 0) {
      throw invalidParams('job_id is required');
    }
    const status = jobs.get(args.job_id);
    if (status === undefined) {
      throw invalidParams(`job ${args.job_id} not found`);
    }
    if (status === 'cancelled') {
      throw invalidParams(`job ${args.job_id} is already cancelled`);
    }
    jobs.set(args.job_id, 'cancelled');
    return textResult(`job ${args.job_id} cancelled`);
  }

  throw new Error(`unknown tool: ${name}`);
}
